"""Unit tests for the game state machine."""

import unittest

from spacefractions.game.engine import Game, GameState
from spacefractions.question.models import Question, QuestionType


def make_question(qid, correct="1/2"):
    return Question(
        id=qid,
        prompt=f"Question {qid}",
        options=("1/2", "3/4", "2/3", "1/3"),
        correct_answer=correct,
        question_type=QuestionType.SIMPLIFY,
    )


class GameTests(unittest.TestCase):
    def test_answers_score_and_finish(self):
        game = Game([make_question(1), make_question(2)])
        result = game.submit_answer("1/2")
        self.assertTrue(result.is_correct)
        self.assertEqual(game.score, 1)
        self.assertEqual(game.state, GameState.PLAYING)
        second = game.submit_answer("wrong")
        self.assertFalse(second.is_correct)
        self.assertTrue(second.finished)
        self.assertEqual(game.state, GameState.GAME_OVER)
        self.assertTrue(game.is_finished())

    def test_pause_resume_blocks_answers(self):
        game = Game([make_question(1)])
        game.pause()
        self.assertEqual(game.state, GameState.PAUSED)
        with self.assertRaises(RuntimeError):
            game.submit_answer("1/2")
        game.resume()
        self.assertEqual(game.state, GameState.PLAYING)
        game.submit_answer("1/2")
        self.assertEqual(game.score, 1)

    def test_empty_question_list_rejected(self):
        with self.assertRaises(ValueError):
            Game([])


if __name__ == "__main__":
    unittest.main()
